function Get-MyWallpaperData {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $disks = Get-CimInstance -ClassName Win32_LogicalDisk `
        -Filter 'DriveType = 3'
    $uptime = (Get-Date) - $os.LastBootUpTime
    $free = $os.FreePhysicalMemory / $os.TotalVisibleMemorySize

    $volumes = [ordered] @{}
    foreach ($disk in $disks) {
        $used = 1 - $disk.FreeSpace / $disk.Size
        $volumes[$disk.DeviceID] = [int] (100 * $used)
    }
    [pscustomobject] @{
        Windows = $os.Caption
        Uptime = '{0} days {1} h' -f $uptime.Days, $uptime.Hours
        Memory = [int] (100 * (1 - $free))
        Volumes = $volumes
    }
}

function Get-MyWallpaperData {
    $key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $windows = Get-ItemProperty -Path $key
    # Your own values, written by the build or the asset process.
    $asset = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Contoso\Asset' `
        -ErrorAction SilentlyContinue

    [pscustomobject] @{
        Release = $windows.DisplayVersion
        Build = '{0}.{1}' -f $windows.CurrentBuild, $windows.UBR
        Team = if ($asset) { $asset.Department } else { 'unassigned' }
        AssetTag = if ($asset) { $asset.Tag } else { 'unknown' }
    }
}

function Get-MyWallpaperData {
    # Needs the RSAT ActiveDirectory module and a domain controller in reach.
    Import-Module ActiveDirectory -ErrorAction Stop
    $user = Get-ADUser -Identity $env:USERNAME -Properties Department, Title
    $computer = Get-ADComputer -Identity $env:COMPUTERNAME `
        -Properties Description, ManagedBy

    [pscustomobject] @{
        User = $user.Name
        Team = '{0} · {1}' -f $user.Department, $user.Title
        Role = $computer.Description
        Owner = if ($computer.ManagedBy) {
            (Get-ADObject -Identity $computer.ManagedBy).Name
        } else { 'not set' }
    }
}

function Get-MyWallpaperData {
    param([string] $ComputerName)
    $uri = "https://cmdb.contoso.com/api/devices/$ComputerName"
    $device = Invoke-RestMethod -Uri $uri -UseDefaultCredentials -TimeoutSec 5

    [pscustomobject] @{
        Owner = $device.owner
        Team = $device.costCenter
        Tickets = $device.openTickets
    }
}

# The function runs in its own runspace: pass in what it needs.
$source = @{
    Name = 'CMDB'
    TimeoutSeconds = 10
    ScriptBlock = ${function:Get-MyWallpaperData}
    ArgumentList = $env:COMPUTERNAME
    Default = $fallback
}
$data = Invoke-BGInfoDataSource @source

function Get-MyWallpaperData {
    # The monitoring tool exports one JSON and one CSV file per machine.
    $share = '\\mon01.contoso.com\exports'
    $status = Get-Content -Path "$share\$env:COMPUTERNAME.json" -Raw |
        ConvertFrom-Json
    $checks = Import-Csv -Path "$share\$env:COMPUTERNAME-checks.csv"

    [pscustomobject] @{
        Cpu = $status.cpu.history         # numbers, oldest first
        Memory = $status.memory.percent
        Tasks = foreach ($check in $checks) {
            @{ Text = $check.Name; Checked = $check.State -eq 'OK' }
        }
    }
}

# The built-in helper: read-only, each probe limited to five seconds.
$facts = Get-BGInfoSystemInfo

# Your own function with the same property names drops in for it.
function Get-MySystemInfo {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $uptime = (Get-Date) - $os.LastBootUpTime
    $volumes = Get-Volume | Where-Object { $_.DriveLetter -and $_.Size }

    [pscustomobject] @{
        ComputerName = $env:COMPUTERNAME
        OSName = $os.Caption
        UptimeText = '{0} days {1} h' -f $uptime.Days, $uptime.Hours
        Disks = foreach ($volume in $volumes) {
            [pscustomobject] @{
                Drive = "$($volume.DriveLetter):"
                FreeGB = [Math]::Round($volume.SizeRemaining / 1GB, 1)
                UsedPercent = [Math]::Round(
                    100 * (1 - $volume.SizeRemaining / $volume.Size), 1)
            }
        }
    }
}
$facts = Get-MySystemInfo

# The presentation code reads the same names either way.
$facts.Disks | New-BGInfoTable -Region Right -Title 'Disks' `
    -Property Drive, FreeGB, UsedPercent
